<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import QRCode from 'qrcode';
import { useAuthStore } from '@/stores/auth';
import { workspaceEntry } from '@/workspace';
import { useRouter } from 'vue-router';
import { parseProductDownloads, downloadSize, type ProductDownloads } from '@/productDownloads';
import AppSheet from '@/components/AppSheet.vue';
const auth = useAuthStore(); const router = useRouter();
const selected = ref(0); const open = ref(false); const qr = ref(''); const error = ref(''); const loading = ref(true);
const downloads = ref<ProductDownloads>({ windows: null, android: null });
const modes = [
  { name: '周期计划', question: '这段时间，怎么安排？', description: '在一个明确的周期里安排日程、任务和休息日，记录计划与实际。', note: '适合备考、学期安排、规律训练。', steps: ['设定起止日期与休息日', '安排每日任务与验收标准', '记录用时，回顾计划与实际'] },
  { name: '目标路线', question: '这个目标，从哪里开始？', description: '把长线目标拆成阶段和步骤。有空就推进，不要求每天完成，也不需要预设结束日期。', note: '适合学吉他、技能学习、长期项目。', steps: ['拆出阶段与可执行步骤', '选择自由推进或前置依赖', '随时暂停，下次接着完成'] },
  { name: '今日待办', question: '今天，还有哪件事？', description: '随手记下一件事，安排日期，逐项完成。不用先创建一个长期计划。', note: '适合取快递、提交材料、临时事项。', steps: ['记下临时事项', '补充日期与备注', '完成后勾选，需要时再找回'] },
];
const mode = computed(() => modes[selected.value]!);
async function enter() { await router.push(auth.user ? await workspaceEntry() : '/login'); }
async function mobileDownload() {
  open.value = true; qr.value = '';
  if (downloads.value.android) {
    try { qr.value = await QRCode.toDataURL(downloads.value.android.url, { width: 256, margin: 2, errorCorrectionLevel: 'M', color: { dark: '#002FA7', light: '#FFFFFF' } }); }
    catch { error.value = '二维码生成失败，请使用直接下载链接。'; }
  }
}
onMounted(async () => {
  try {
    const response = await fetch('/downloads/manifest.json', { cache: 'no-store' });
    if (!response.ok) throw new Error('下载清单暂不可用。');
    downloads.value = parseProductDownloads(await response.json(), location.origin);
  } catch { error.value = '暂时无法获取下载清单，请稍后重试。'; }
  finally { loading.value = false; }
});
</script>
<template><div class="product-home">
  <header class="product-header"><router-link to="/welcome" class="product-brand">计划舱</router-link><nav aria-label="官网导航"><a href="#ways">使用方式</a><a href="#clients">客户端下载</a><button class="btn primary" @click="enter">进入网页版</button></nav></header>
  <section class="product-hero"><div class="product-hero-copy"><p class="product-intro">周期计划 / 目标路线 / 今日待办</p><h1>把今天安排好。<br/><span>把目标走下去。</span></h1><p class="product-description">有规律的日程，有空时推进的目标，临时想到的事。<br/>用三种独立的方式，管理自己的行动。</p><div class="product-actions"><button class="btn primary" @click="enter">开始使用网页版</button><a class="btn" href="#clients">下载客户端</a></div><p class="product-footnote">开源 · 多用户 · 跨设备同步</p></div>
    <div class="product-preview" aria-label="产品使用方式示例"><div class="preview-heading"><span>三种方式，一个行动入口</span><small>示例</small></div><div class="preview-tabs" role="tablist" aria-label="使用方式预览"><button v-for="(item,index) in modes" :id="`mode-tab-${index}`" :key="item.name" role="tab" :aria-selected="selected === index" aria-controls="mode-preview" :class="{ active: selected === index }" @click="selected = index">{{ item.name }}</button></div><div id="mode-preview" class="preview-content" role="tabpanel" :aria-labelledby="`mode-tab-${selected}`"><span class="preview-number">0{{ selected + 1 }}</span><h2>{{ mode.question }}</h2><ol><li v-for="step in mode.steps" :key="step">{{ step }}</li></ol><p>{{ mode.note }}</p></div></div>
  </section>
  <section id="ways" class="product-section"><header><span>01</span><div><h2>让任务适应你的生活。</h2><p>不把每件事都塞进同一套规则。</p></div></header><div class="product-mode-grid"><article v-for="(item,index) in modes" :key="item.name"><span class="mode-number">0{{ index + 1 }}</span><h3>{{ item.name }}</h3><p>{{ item.description }}</p><small>{{ item.note }}</small></article></div></section>
  <section class="product-section product-capabilities"><header><span>02</span><div><h2>换一个设备，继续做。</h2><p>网页、Windows 和 Android 复用同一套账号与业务接口。</p></div></header><div class="product-feature-grid"><article><h3>你的账号，你的数据</h3><p>计划与任务按用户隔离。支持邀请注册、会话管理与数据导出。</p></article><article><h3>网络断开，也能保留行动</h3><p>支持已缓存内容的离线浏览及部分编辑。离线操作留在本机，联网后可同步；未缓存内容仍需联网。</p></article><article><h3>有冲突，不直接覆盖</h3><p>两端修改同一记录时，保留本地操作并提示处理。不会把最新的服务器内容静默覆盖。</p></article></div></section>
  <section id="clients" class="product-section"><header><span>03</span><div><h2>选择你的使用入口。</h2><p>安装包发布后在这里下载；更新安装由你确认。</p></div></header><p v-if="error" class="error-text" role="status">{{ error }}</p><div class="product-client-grid"><article><h3>浏览器</h3><p>无需安装，登录后使用。电脑和手机浏览器均可访问。</p><button class="btn primary" @click="enter">进入网页版</button></article><article><h3>Windows 电脑</h3><p>独立桌面客户端，可配置服务器，支持应用内更新。</p><a v-if="downloads.windows" class="btn primary" :href="downloads.windows.url" download>下载 Windows 安装包</a><button v-else class="btn" disabled>{{ loading ? '检查发布状态…' : '正式安装包尚未发布' }}</button><small v-if="downloads.windows">{{ downloads.windows.version }} · {{ downloadSize(downloads.windows.bytes) }}</small></article><article><h3>Android 手机</h3><p>电脑上扫描二维码下载 APK；手机上可以直接下载。</p><button class="btn" :disabled="loading" @click="mobileDownload">{{ downloads.android ? '扫码下载 Android' : '查看 Android 发布状态' }}</button><small v-if="downloads.android">{{ downloads.android.version }} · {{ downloadSize(downloads.android.bytes) }}</small><small v-else>正式安装包尚未发布，不提供调试包。</small></article></div></section>
  <footer class="product-footer"><div><strong>计划舱</strong><span>规划有节奏，行动有积累。</span></div><a href="https://beian.miit.gov.cn/" target="_blank" rel="noopener noreferrer">鄂ICP备2026050813号-1</a><router-link to="/login">账号登录</router-link></footer>
  <AppSheet :open="open" title="Android 客户端下载" title-id="android-download-title" @close="open = false"><template v-if="downloads.android"><p>扫描二维码，在手机浏览器中下载 APK。</p><img v-if="qr" class="download-qr" :src="qr" alt="Android 安装包下载二维码" width="256" height="256"/><p><a class="btn primary" :href="downloads.android.url" download>直接下载 APK</a></p><p>{{ downloads.android.version }} · {{ downloadSize(downloads.android.bytes) }}</p><details><summary>查看 SHA-256 校验值</summary><code class="download-hash">{{ downloads.android.sha256 }}</code></details><p class="helper-text">安装时 Android 可能要求允许浏览器安装应用。只从本站获取安装包；二维码不包含账号或密码。</p></template><p v-else>Android 正式签名包尚未发布。完成发布与验收后，这里会提供下载二维码；现在可先使用网页版。</p></AppSheet>
</div></template>
